<?php

namespace Database\Seeders;

use App\Models\Mishap;
use App\Support\HazardClassifier;
use Illuminate\Database\Seeder;

/**
 * Historical mishap records for CY 2016-2026, imported from the 15SW
 * "Historical Record of Mishaps" workbook. Idempotent: keyed on date +
 * location + description so a re-seed never duplicates a row.
 */
class MishapSeeder extends Seeder
{
    public function run(): void
    {
        foreach ($this->records() as $r) {
            Mishap::updateOrCreate(
                [
                    'mishap_date' => $r['date'],
                    'location' => $r['location'],
                    'description' => $r['desc'],
                ],
                [
                    'mishap_type' => $r['type'],
                    'environment' => $r['env'],
                    'cause' => HazardClassifier::primary($r['desc']),
                ],
            );
        }
    }

